// JSON type detection helpers, mirroring Python jsonschema's type checks.
//
// In Python, `json.loads` distinguishes int/float/bool; `True` is an instance
// of `int` but jsonschema explicitly excludes booleans from number/integer.
// In JS, booleans and numbers are distinct primitives, and JSON numbers that
// are integral (including those parsed from "1.0") count as "integer", which
// matches jsonschema's "integer means a number with zero fractional part".

export function jtype(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  const t = typeof value;
  if (t === "number") return Number.isInteger(value) ? "integer" : "number";
  if (t === "string") return "string";
  if (t === "boolean") return "boolean";
  return "object";
}

export function isType(value, type) {
  switch (type) {
    case "null":
      return value === null;
    case "boolean":
      return typeof value === "boolean";
    case "string":
      return typeof value === "string";
    case "array":
      return Array.isArray(value);
    case "object":
      return value !== null && typeof value === "object" && !Array.isArray(value);
    case "number":
      return typeof value === "number";
    case "integer":
      return typeof value === "number" && Number.isInteger(value);
    default:
      return false;
  }
}

// Number of characters as Python's len(str) counts them (code points).
export function codePointLength(str) {
  let n = 0;
  for (const _ch of str) n += 1;
  return n;
}

