// ValidationError: mirrors jsonschema.exceptions.ValidationError.
// Only the attributes observable by the program matter: `path` (used by
// ErrorTree) and `context` (sub-errors of anyOf/oneOf/not style failures).

export class ValidationError extends Error {
  constructor(message, path = [], context = []) {
    super(message);
    this.name = "ValidationError";
    this.message = message;
    this.path = path;
    this.context = context;
  }
}

// SchemaError: raised by check_schema when a schema is invalid against the
// meta-schema (mirrors jsonschema.exceptions.SchemaError). The Python program
// crashes with a traceback in this case; the caller exits non-zero with no
// stdout, matching that observable behaviour.

export class SchemaError extends Error {
  constructor(message) {
    super(message);
    this.name = "SchemaError";
  }
}

