args.content:
// Keyword validation engine.
//
// `descend(v, instance, schema, path)` yields one ValidationError per failed
// keyword, descending into subschemas exactly the way the Python `jsonschema`
// package's `iter_errors` does:
//   - allOf yields the errors of each failing subschema directly,
//   - anyOf / oneOf / not yield a single error (with sub-errors as context),
//   - required / dependent* yield one error per missing property,
//   - additionalProperties: false yields a single error for all extras,
//   - propertyNames yields the name-schema errors per property,
//   - contains yields a single error.
//
// Draft differences are driven by flags on `v.config` (see drafts.mjs).

import { isType, jtype, codePointLength } from "./jtype.mjs";
import { pyEqual } from "./pyEqual.mjs";
import { ValidationError } from "./errors.mjs";

// Resolve a same-document JSON Pointer reference ("#/definitions/foo", "#").
export function resolvePointer(root, ref) {
  if (ref === "#" || ref === "") return root;
  if (!ref.startsWith("#/")) {
    throw new Error(`Unresolvable JSON reference: ${ref}`);
  }
  let node = root;
  for (const rawSeg of ref.slice(2).split("/")) {
    const seg = decodeURIComponent(rawSeg).replace(/~1/g, "/").replace(/~0/g, "~");
    if (node === null || typeof node !== "object") {
      throw new Error(`Unresolvable JSON reference: ${ref}`);
    }
    node = Array.isArray(node) ? node[Number(seg)] : node[seg];
    if (node === undefined) {
      throw new Error(`Unresolvable JSON reference: ${ref}`);
    }
  }
  return node;
}

function subErrors(v, instance, schema, path) {
  return [...descend(v, instance, schema, path)];
}

function subIsValid(v, instance, schema, path) {
  return descend(v, instance, schema, path).next().done;
}

export function* descend(v, instance, schema, path) {
  if (schema === true) return;
  if (schema === false) {
    yield new ValidationError("False schema does not allow the instance", path);
    return;
  }
  const cfg = v.config;

  // $ref: in drafts 4-7 it replaces all sibling keywords; from 2019-09 on it
  // is evaluated alongside them.
  if (typeof schema.$ref === "string") {
    const target = resolvePointer(v.schema, schema.$ref);
    yield* descend(v, instance, target, path);
    if (cfg.refReplacesSiblings) return;
  }

  yield* typeKeyword(schema, instance, path);

  if (schema.enum !== undefined) {
    if (!schema.enum.some((each) => pyEqual(each, instance))) {
      yield new ValidationError("instance is not one of the enum values", path);
    }
  }
  if (cfg.hasConst && schema.const !== undefined) {
    if (!pyEqual(schema.const, instance)) {
      yield new ValidationError("const mismatch", path);
    }
  }

  yield* numericKeywords(cfg, schema, instance, path);
  yield* stringKeywords(schema, instance, path);
  yield* arrayKeywords(v, cfg, schema, instance, path);
  yield* objectKeywords(v, cfg, schema, instance, path);
  yield* applicatorKeywords(v, cfg, schema, instance, path);
}

function* typeKeyword(schema, instance, path) {
  if (schema.type === undefined) return;
  const types = Array.isArray(schema.type) ? schema.type : [schema.type];
  if (!types.some((t) => isType(instance, t))) {
    yield new ValidationError(
      `${JSON.stringify(instance)} is not of type ${types.map((t) => `'${t}'`).join(", ")}`,
      path,
    );
  }
}

function* numericKeywords(cfg, schema, instance, path) {
  if (typeof instance !== "number") return;

  if (schema.multipleOf !== undefined) {
    const dB = schema.multipleOf;
    let failed;
    if (!Number.isInteger(dB)) {
      // Python: isinstance(dB, float) -> quotient = instance / dB;
      // failed = int(quotient) != quotient
      const quotient = instance / dB;
      failed = Math.trunc(quotient) !== quotient;
    } else {
      failed = instance % dB !== 0;
    }
    if (failed) {
      yield new ValidationError(`${instance} is not a multiple of ${dB}`, path);
    }
  }

  if (cfg.exclusiveIsNumber) {
    // Draft 6+: exclusiveMinimum / exclusiveMaximum are numbers.
    if (schema.exclusiveMinimum !== undefined && instance <= schema.exclusiveMinimum) {
      yield new ValidationError(`${instance} is less than or equal to the minimum of ${schema.exclusiveMinimum}`, path);
    }
    if (schema.minimum !== undefined && instance < schema.minimum) {
      yield new ValidationError(`${instance} is less than the minimum of ${schema.minimum}`, path);
    }
    if (schema.exclusiveMaximum !== undefined && instance >= schema.exclusiveMaximum) {
      yield new ValidationError(`${instance} is greater than or equal to the maximum of ${schema.exclusiveMaximum}`, path);
    }
    if (schema.maximum !== undefined && instance > schema.maximum) {
      yield new ValidationError(`${instance} is greater than the maximum of ${schema.maximum}`, path);
    }
  } else {
    // Draft 4: exclusiveMinimum / exclusiveMaximum are boolean modifiers.
    if (schema.minimum !== undefined) {
      const exclusive = schema.exclusiveMinimum === true;
      if (exclusive ? instance <= schema.minimum : instance < schema.minimum) {
        yield new ValidationError(`${instance} is less than the minimum of ${schema.minimum}`, path);
      }
    }
    if (schema.maximum !== undefined) {
      const exclusive = schema.exclusiveMaximum === true;
      if (exclusive ? instance >= schema.maximum : instance > schema.maximum) {
        yield new ValidationError(`${instance} is greater than the maximum of ${schema.maximum}`, path);
      }
    }
  }
}

function* stringKeywords(schema, instance, path) {
  if (typeof instance !== "string") return;
  if (schema.maxLength !== undefined && codePointLength(instance) > schema.maxLength) {
    yield new ValidationError(`${JSON.stringify(instance)} is too long`, path);
  }
  if (schema.minLength !== undefined && codePointLength(instance) < schema.minLength) {
    yield new ValidationError(`${JSON.stringify(instance)} is too short`, path);
  }
  if (schema.pattern !== undefined) {
    const re = new RegExp(schema.pattern);
    if (!re.test(instance)) {
      yield new ValidationError(`${JSON.stringify(instance)} does not match ${JSON.stringify(schema.pattern)}`, path);
    }
  }
}

function* arrayKeywords(v, cfg, schema, instance, path) {
  if (!Array.isArray(instance)) return;

  if (schema.maxItems !== undefined && instance.length > schema.maxItems) {
    yield new ValidationError(`${JSON.stringify(instance)} is too long`, path);
  }
  if (schema.minItems !== undefined && instance.length < schema.minItems) {
    yield new ValidationError(`${JSON.stringify(instance)} is too short`, path);
  }
  if (schema.uniqueItems === true) {
    let dup = false;
    outer: for (let i = 0; i < instance.length; i += 1) {
      for (let j = i + 1; j < instance.length; j += 1) {
        if (pyEqual(instance[i], instance[j])) {
          dup = true;
          break outer;
        }
      }
    }
    if (dup) {
      yield new ValidationError(`${JSON.stringify(instance)} has non-unique elements`, path);
    }
  }

  if (cfg.prefixItems) {
    // Draft 2020-12: prefixItems is the tuple form, items applies to the rest.
    const prefix = Array.isArray(schema.prefixItems) ? schema.prefixItems : [];
    for (let i = 0; i < Math.min(prefix.length, instance.length); i += 1) {
      yield* descend(v, instance[i], prefix[i], path.concat(i));
    }
    if (schema.items !== undefined && instance.length > prefix.length) {
      for (let i = prefix.length; i < instance.length; i += 1) {
        yield* descend(v, instance[i], schema.items, path.concat(i));
      }
    }
  } else if (Array.isArray(schema.items)) {
    // Drafts 4 - 2019-09: items array is the tuple form.
    const tuple = schema.items;
    for (let i = 0; i < Math.min(tuple.length, instance.length); i += 1) {
      yield* descend(v, instance[i], tuple[i], path.concat(i));
    }
    if (instance.length > tuple.length && schema.additionalItems !== undefined) {
      if (schema.additionalItems === false) {
        yield new ValidationError("Additional items are not allowed", path);
      } else if (schema.additionalItems !== true) {
        for (let i = tuple.length; i < instance.length; i += 1) {
          yield* descend(v, instance[i], schema.additionalItems, path.concat(i));
        }
      }
    }
  } else if (schema.items !== undefined) {
    for (let i = 0; i < instance.length; i += 1) {
      yield* descend(v, instance[i], schema.items, path.concat(i));
    }
  }

  if (cfg.hasContains && schema.contains !== undefined) {
    let matches = 0;
    for (let i = 0; i < instance.length; i += 1) {
      if (subIsValid(v, instance[i], schema.contains, path.concat(i))) matches += 1;
    }
    if (cfg.hasMinMaxContains) {
      const minContains = schema.minContains === undefined ? 1 : schema.minContains;
      const maxContains = schema.maxContains;
      if (matches < minContains) {
        yield new ValidationError("Too few items match the given schema", path);
      } else if (maxContains !== undefined && matches > maxContains) {
        yield new ValidationError("Too many items match the given schema", path);
      }
    } else if (matches === 0) {
      yield new ValidationError(
        `${JSON.stringify(instance)} does not contain items matching the given schema`,
        path,
      );
    }
  }

  if (cfg.hasUnevaluated && schema.unevaluatedItems !== undefined) {
    const evaluated = findEvaluatedItemIndexes(v, instance, schema);
    const extras = [];
    for (let i = 0; i < instance.length; i += 1) {
      if (!evaluated.has(i)) extras.push(i);
    }
    if (extras.length > 0) {
      if (schema.unevaluatedItems === false) {
        yield new ValidationError("Unevaluated items are not allowed", path);
      } else if (schema.unevaluatedItems !== true) {
        for (const i of extras) {
          yield* descend(v, instance[i], schema.unevaluatedItems, path.concat(i));
        }
      }
    }
  }
}

function* objectKeywords(v, cfg, schema, instance, path) {
  if (!isType(instance, "object")) return;

  if (schema.maxProperties !== undefined && Object.keys(instance).length > schema.maxProperties) {
    yield new ValidationError(`${JSON.stringify(instance)} has too many properties`, path);
  }
  if (schema.minProperties !== undefined && Object.keys(instance).length < schema.minProperties) {
    yield new ValidationError(`${JSON.stringify(instance)} does not have enough properties`, path);
  }

  if (Array.isArray(schema.required)) {
    for (const name of schema.required) {
      if (!Object.prototype.hasOwnProperty.call(instance, name)) {
        yield new ValidationError(`'${name}' is a required property`, path);
      }
    }
  }

  const properties = isType(schema.properties, "object") ? schema.properties : {};
  const patterns = isType(schema.patternProperties, "object") ? schema.patternProperties : {};

  for (const [name, subschema] of Object.entries(properties)) {
    if (Object.prototype.hasOwnProperty.call(instance, name)) {
      yield* descend(v, instance[name], subschema, path.concat(name));
    }
  }
  for (const [pattern, subschema] of Object.entries(patterns)) {
    const re = new RegExp(pattern);
    for (const name of Object.keys(instance)) {
      if (re.test(name)) {
        yield* descend(v, instance[name], subschema, path.concat(name));
      }
    }
  }

  if (schema.additionalProperties !== undefined) {
    const extras = Object.keys(instance).filter(
      (name) =>
        !Object.prototype.hasOwnProperty.call(properties, name) &&
        !Object.keys(patterns).some((pattern) => new RegExp(pattern).test(name)),
    );
    if (extras.length > 0) {
      if (schema.additionalProperties === false) {
        yield new ValidationError(
          `Additional properties are not allowed (${extras.map((e) => `'${e}'`).join(", ")} unexpected)`,
          path,
        );
      } else if (schema.additionalProperties !== true) {
        for (const name of extras) {
          yield* descend(v, instance[name], schema.additionalProperties, path.concat(name));
        }
      }
    }
  }

  if (cfg.hasPropertyNames && schema.propertyNames !== undefined) {
    for (const name of Object.keys(instance)) {
      yield* descend(v, name, schema.propertyNames, path.concat(name));
    }
  }

  if (cfg.hasDependencies && isType(schema.dependencies, "object")) {
    for (const [name, dependency] of Object.entries(schema.dependencies)) {
      if (!Object.prototype.hasOwnProperty.call(instance, name)) continue;
      if (Array.isArray(dependency)) {
        for (const dep of dependency) {
          if (!Object.prototype.hasOwnProperty.call(instance, dep)) {
            yield new ValidationError(`'${dep}' is a dependency of '${name}'`, path);
          }
        }
      } else {
        yield* descend(v, instance, dependency, path);
      }
    }
  }

  if (cfg.hasDependents) {
    if (isType(schema.dependentRequired, "object")) {
      for (const [name, deps] of Object.entries(schema.dependentRequired)) {
        if (!Object.prototype.hasOwnProperty.call(instance, name)) continue;
        for (const dep of deps) {
          if (!Object.prototype.hasOwnProperty.call(instance, dep)) {
            yield new ValidationError(`'${dep}' is a dependency of '${name}'`, path);
          }
        }
      }
    }
    if (isType(schema.dependentSchemas, "object")) {
      for (const [name, subschema] of Object.entries(schema.dependentSchemas)) {
        if (!Object.prototype.hasOwnProperty.call(instance, name)) continue;
        yield* descend(v, instance, subschema, path);
      }
    }
  }

  if (cfg.hasUnevaluated && schema.unevaluatedProperties !== undefined) {
    const evaluated = findEvaluatedPropertyKeys(v, instance, schema);
    const extras = Object.keys(instance).filter((name) => !evaluated.has(name));
    if (extras.length > 0) {
      if (schema.unevaluatedProperties === false) {
        yield new ValidationError("Unevaluated properties are not allowed", path);
      } else if (schema.unevaluatedProperties !== true) {
        for (const name of extras) {
          yield* descend(v, instance[name], schema.unevaluatedProperties, path.concat(name));
        }
      }
    }
  }
}

function* applicatorKeywords(v, cfg, schema, instance, path) {
  if (Array.isArray(schema.allOf)) {
    for (let i = 0; i < schema.allOf.length; i += 1) {
      yield* descend(v, instance, schema.allOf[i], path);
    }
  }

  if (Array.isArray(schema.anyOf)) {
    const context = [];
    let valid = false;
    for (const subschema of schema.anyOf) {
      const errs = subErrors(v, instance, subschema, path);
      if (errs.length === 0) {
        valid = true;
        break;
      }
      context.push(...errs);
    }
    if (!valid) {
      yield new ValidationError(
        `${JSON.stringify(instance)} is not valid under any of the given schemas`,
        path,
        context,
      );
    }
  }

  if (Array.isArray(schema.oneOf)) {
    const context = [];
    let valids = 0;
    for (const subschema of schema.oneOf) {
      const errs = subErrors(v, instance, subschema, path);
      if (errs.length === 0) valids += 1;
      else context.push(...errs);
    }
    if (valids !== 1) {
      yield new ValidationError(
        `${JSON.stringify(instance)} is not valid under one of the given schemas`,
        path,
        context,
      );
    }
  }

  if (schema.not !== undefined) {
    if (subIsValid(v, instance, schema.not, path)) {
      yield new ValidationError(`${JSON.stringify(instance)} should not be valid under the given schema`, path);
    }
  }

  if (cfg.hasIfThenElse && schema.if !== undefined) {
    if (subIsValid(v, instance, schema.if, path)) {
      if (schema.then !== undefined) {
        yield* descend(v, instance, schema.then, path);
      }
    } else if (schema.else !== undefined) {
      yield* descend(v, instance, schema.else, path);
    }
  }
}

// --- "evaluated" annotation tracking for unevaluated* keywords -------------

function mergeInto(target, source) {
  for (const item of source) target.add(item);
}

function findEvaluatedPropertyKeys(v, instance, schema, seen = new Set()) {
  const evaluated = new Set();
  if (!isType(schema, "object")) return evaluated;
  if (seen.has(schema)) return evaluated;
  seen.add(schema);

  if (typeof schema.$ref === "string") {
    mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, resolvePointer(v.schema, schema.$ref), seen));
  }
  if (isType(schema.properties, "object")) {
    for (const name of Object.keys(schema.properties)) {
      if (Object.prototype.hasOwnProperty.call(instance, name)) evaluated.add(name);
    }
  }
  if (isType(schema.patternProperties, "object")) {
    for (const pattern of Object.keys(schema.patternProperties)) {
      const re = new RegExp(pattern);
      for (const name of Object.keys(instance)) {
        if (re.test(name)) evaluated.add(name);
      }
    }
  }
  if (schema.additionalProperties !== undefined) {
    for (const name of Object.keys(instance)) evaluated.add(name);
  }
  if (Array.isArray(schema.allOf)) {
    for (const sub of schema.allOf) {
      mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
    }
  }
  if (Array.isArray(schema.anyOf)) {
    for (const sub of schema.anyOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
      }
    }
  }
  if (Array.isArray(schema.oneOf)) {
    for (const sub of schema.oneOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
      }
    }
  }
  if (schema.if !== undefined) {
    if (subIsValid(v, instance, schema.if, [])) {
      mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, schema.if, seen));
      if (schema.then !== undefined) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, schema.then, seen));
      }
    } else if (schema.else !== undefined) {
      mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, schema.else, seen));
    }
  }
  if (isType(schema.dependentSchemas, "object")) {
    for (const [name, sub] of Object.entries(schema.dependentSchemas)) {
      if (Object.prototype.hasOwnProperty.call(instance, name)) {
        mergeInto(evaluated, findEvaluatedPropertyKeys(v, instance, sub, seen));
      }
    }
  }
  return evaluated;
}

function findEvaluatedItemIndexes(v, instance, schema, seen = new Set()) {
  const evaluated = new Set();
  if (!isType(schema, "object")) return evaluated;
  if (seen.has(schema)) return evaluated;
  seen.add(schema);

  const addAll = () => {
    for (let i = 0; i < instance.length; i += 1) evaluated.add(i);
  };

  if (typeof schema.$ref === "string") {
    mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, resolvePointer(v.schema, schema.$ref), seen));
  }
  if (Array.isArray(schema.prefixItems)) {
    for (let i = 0; i < Math.min(schema.prefixItems.length, instance.length); i += 1) evaluated.add(i);
    if (schema.items !== undefined) addAll();
  } else if (Array.isArray(schema.items)) {
    for (let i = 0; i < Math.min(schema.items.length, instance.length); i += 1) evaluated.add(i);
    if (schema.additionalItems !== undefined) addAll();
  } else if (schema.items !== undefined) {
    addAll();
  }
  if (Array.isArray(schema.allOf)) {
    for (const sub of schema.allOf) {
      mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, sub, seen));
    }
  }
  if (Array.isArray(schema.anyOf)) {
    for (const sub of schema.anyOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, sub, seen));
      }
    }
  }
  if (Array.isArray(schema.oneOf)) {
    for (const sub of schema.oneOf) {
      if (subIsValid(v, instance, sub, [])) {
        mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, sub, seen));
      }
    }
  }
  if (schema.if !== undefined) {
    if (subIsValid(v, instance, schema.if, [])) {
      mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, schema.if, seen));
      if (schema.then !== undefined) {
        mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, schema.then, seen));
      }
    } else if (schema.else !== undefined) {
      mergeInto(evaluated, findEvaluatedItemIndexes(v, instance, schema.else, seen));
    }
  }
  return evaluated;
}

