// Meta-schema validation (check_schema).
//
// The Python program runs Draft4/6/7/2019-09/2020-12 check_schema in order and
// crashes with a SchemaError (no stdout, non-zero exit) on the first failure.
// Observable consequence: a schema survives only if it is valid under *all*
// five meta-schemas. This module enforces that union, recursively, including:
//   - no boolean schemas anywhere (draft-04 meta-schema only allows objects),
//   - exclusiveMinimum / exclusiveMaximum can never appear (draft-04 requires
//     booleans, draft-6+ require numbers, so every occurrence fails one of them),
//   - keyword value shapes (types, non-negative integers, string arrays, ...).
//
// Unknown keywords are allowed, as in every meta-schema.

import { SchemaError } from "./errors.mjs";
import { isType } from "./jtype.mjs";

const VALID_TYPES = new Set(["array", "boolean", "integer", "null", "number", "object", "string"]);

function fail(message) {
  throw new SchemaError(message);
}

function checkSubschema(value, where) {
  if (typeof value === "boolean") {
    fail(`${JSON.stringify(value)} is not of type 'object' (in ${where})`);
  }
  if (!isType(value, "object")) {
    fail(`${JSON.stringify(value)} is not of type 'object' (in ${where})`);
  }
  checkNode(value, where);
}

function checkNonNegativeInteger(value, keyword) {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) {
    fail(`${JSON.stringify(value)} is not valid for '${keyword}' (non-negative integer expected)`);
  }
}

function checkStringArray(value, keyword, { minItems }) {
  if (!Array.isArray(value)) {
    fail(`${JSON.stringify(value)} is not of type 'array' (in '${keyword}')`);
  }
  if (minItems !== undefined && value.length < minItems) {
    fail(`${JSON.stringify(value)} is too short (in '${keyword}')`);
  }
  const seen = new Set();
  for (const item of value) {
    if (typeof item !== "string") {
      fail(`${JSON.stringify(item)} is not of type 'string' (in '${keyword}')`);
    }
    if (seen.has(item)) {
      fail(`${JSON.stringify(value)} has non-unique elements (in '${keyword}')`);
    }
    seen.add(item);
  }
}

function checkSchemaOrArray(value, keyword, { minItemsForArray }) {
  if (Array.isArray(value)) {
    if (minItemsForArray !== undefined && value.length < minItemsForArray) {
