// Validator base machinery: builds a validator class per draft configuration,
// mirroring jsonschema's Draft*Validator classes.

import { descend } from "./keywords.mjs";
import { checkSchema } from "./metaCheck.mjs";

export function createValidatorClass(name, config) {
  const cls = class {
    constructor(schema) {
      this.schema = schema;
      this.config = config;
    }

    *iter_errors(instance) {
      yield* descend(this, instance, this.schema, []);
    }

    is_valid(instance) {
      return this.iter_errors(instance).next().done;
    }

    check_schema(schema) {
      checkSchema(schema);
      return undefined; // Python returns None
    }

    evolve(changes = {}) {
      const schema = Object.prototype.hasOwnProperty.call(changes, "schema")
        ? changes.schema
        : this.schema;
      return new this.constructor(schema);
    }
  };
  Object.defineProperty(cls, "name", { value: name, configurable: true });
  return cls;
}

