// Draft configurations and validator classes, plus validator_for().
//
// Behavioural differences between drafts (as observed from the executable):
//   - draft 4:     $ref replaces siblings; boolean exclusive* modifiers;
//                  `dependencies`; no const/contains/propertyNames/if-then-else
//   - draft 6:     adds const, contains, propertyNames; numeric exclusive*
//   - draft 7:     adds if/then/else
//   - 2019-09:     $ref alongside siblings; drops `dependencies`; adds
//                  dependentRequired/dependentSchemas, min/maxContains,
//                  unevaluated*
//   - 2020-12:     items becomes single-schema; prefixItems is the tuple form

import { createValidatorClass } from "./validator.mjs";

const base = {
  refReplacesSiblings: true,
  exclusiveIsNumber: false,
  hasConst: false,
  hasContains: false,
  hasPropertyNames: false,
  hasIfThenElse: false,
  hasDependencies: true,
  hasDependents: false,
  hasMinMaxContains: false,
  hasUnevaluated: false,
  prefixItems: false,
};

const DRAFT4 = { ...base };

const DRAFT6 = {
  ...base,
  exclusiveIsNumber: true,
  hasConst: true,
  hasContains: true,
  hasPropertyNames: true,
};

const DRAFT7 = {
  ...DRAFT6,
  hasIfThenElse: true,
};

const DRAFT201909 = {
  ...DRAFT7,
  refReplacesSiblings: false,
  hasDependencies: false,
  hasDependents: true,
  hasMinMaxContains: true,
  hasUnevaluated: true,
};

const DRAFT202012 = {
  ...DRAFT201909,
  prefixItems: true,
};

export const Draft4Validator = createValidatorClass("Draft4Validator", DRAFT4);
export const Draft6Validator = createValidatorClass("Draft6Validator", DRAFT6);
export const Draft7Validator = createValidatorClass("Draft7Validator", DRAFT7);
export const Draft201909Validator = createValidatorClass("Draft201909Validator", DRAFT201909);
export const Draft202012Validator = createValidatorClass("Draft202012Validator", DRAFT202012);

const META_SCHEMA_VALIDATORS = new Map([
  ["http://json-schema.org/draft-04/schema", Draft4Validator],
  ["http://json-schema.org/draft-06/schema", Draft6Validator],
  ["http://json-schema.org/draft-07/schema", Draft7Validator],
  ["https://json-schema.org/draft/2019-09/schema", Draft201909Validator],
  ["https://json-schema.org/draft/2020-12/schema", Draft202012Validator],
]);

// Mirrors jsonschema.validators.validator_for: picks the validator class whose
// meta-schema matches the schema's "$schema" keyword; defaults to the latest
// draft when missing or unknown. A trailing "#" on the URI is ignored.
export function validator_for(schema) {
  let uri = "";
  if (schema !== null && typeof schema === "object" && !Array.isArray(schema)) {
    const declared = schema.$schema;
    if (typeof declared === "string") uri = declared;
  }
  const normalized = uri.endsWith("#") ? uri.slice(0, -1) : uri;
  return META_SCHEMA_VALIDATORS.get(normalized) || Draft202012Validator;
}

