// ErrorTree: mirrors jsonschema.exceptions.ErrorTree.
// Errors are placed in a tree keyed by their instance path; `total_errors`
// counts every error in the tree, including children (context sub-errors of
// anyOf/oneOf are NOT part of the tree, matching jsonschema).

export class ErrorTree {
  constructor(errors = []) {
    this.errors = {};
    this._contents = {};
    this._allErrors = [];
    for (const error of errors) {
      this._allErrors.push(error);
      let node = this;
      for (const segment of error.path) {
        if (!Object.prototype.hasOwnProperty.call(node._contents, segment)) {
          const child = new ErrorTree();
          node._contents[segment] = child;
        }
        node = node._contents[segment];
      }
      node._allErrors.push(error);
      node.errors[node._allErrors.length - 1] = error;
    }
    this.total_errors = this._computeTotal();
  }

  _computeTotal() {
    let total = this._allErrors.length;
    for (const child of Object.values(this._contents)) {
      total += child._computeTotal();
    }
    return total;
  }
}

