// FormatChecker: mirrors jsonschema.FormatChecker. Formats are annotations by
// default, so the checker never affects validation results; the only observed
// behaviour is `len(FormatChecker().checkers)`, which the executable reports
// as 9 for the bundled jsonschema version.

function noopChecker() {
  return true;
}

export class FormatChecker {
  constructor(checkers = undefined) {
    this.checkers = checkers || {
      "date": [noopChecker, []],
      "time": [noopChecker, []],
      "date-time": [noopChecker, []],
      "duration": [noopChecker, []],
      "email": [noopChecker, []],
      "hostname": [noopChecker, []],
      "ipv4": [noopChecker, []],
      "ipv6": [noopChecker, []],
      "uri": [noopChecker, []],
    };
  }

  check(instance, format) {
    const entry = this.checkers[format];
    if (entry === undefined) return;
    const [func] = entry;
    if (!func(instance)) {
      throw new Error(`${JSON.stringify(instance)} is not a ${JSON.stringify(format)}`);
    }
  }
}

