// JSON type detection helpers, mirroring Python jsonschema's type checks.
//
// Numbers parsed from float syntax (3.0, 1e2) are boxed `Number` objects (see
// pyjson.mjs) so that "integer" only matches genuine Python ints. Booleans are
// never numbers, matching jsonschema's exclusion of Python's bool (a subclass
// of int there).

export function isNumber(value) {
  return typeof value === "number" || value instanceof Number;
}

export function unwrap(value) {
  return value instanceof Number ? value.valueOf() : value;
}

export function jtype(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (typeof value === "number") return Number.isInteger(value) ? "integer" : "number";
  if (value instanceof Number) return "number"; // Python float, even if integral
  const t = typeof value;
  if (t === "string") return "string";
  if (t === "boolean") return "boolean";
  return "object";
}

export function isType(value, type) {
  switch (type) {
    case "null":
      return value === null;
    case "boolean":
      return typeof value === "boolean";
    case "string":
      return typeof value === "string";
    case "array":
      return Array.isArray(value);
    case "object":
      return value !== null && typeof value === "object" && !Array.isArray(value) && !(value instanceof Number);
    case "number":
      return isNumber(value);
    case "integer":
      // Only genuine ints; floats with zero fractional part do not qualify.
      return typeof value === "number" && Number.isInteger(value);
    default:
      return false;
  }
}

// Number of characters as Python's len(str) counts them (code points).
export function codePointLength(str) {
  let n = 0;
  for (const _ch of str) n += 1;
  return n;
}

