// Deep equality with Python-flavoured semantics as used by jsonschema for
// `enum`, `const` and `uniqueItems`:
//   - numbers compare by numeric value (1 == 1.0, boxed floats unwrapped),
//   - booleans are NOT equal to numbers (jsonschema "unbools" before
//     comparing, so True does not equal 1),
//   - arrays compare element-wise, objects compare key-wise (order-free).

import { jtype, unwrap } from "./jtype.mjs";

function isNumeric(t) {
  return t === "number" || t === "integer";
}

export function pyEqual(a, b) {
  const ta = jtype(a);
  const tb = jtype(b);

  if (isNumeric(ta) && isNumeric(tb)) return unwrap(a) === unwrap(b);
  if (ta !== tb) return false;

  switch (ta) {
    case "array": {
      if (a.length !== b.length) return false;
      for (let i = 0; i < a.length; i += 1) {
        if (!pyEqual(a[i], b[i])) return false;
      }
      return true;
    }
    case "object": {
      const ka = Object.keys(a);
      const kb = Object.keys(b);
      if (ka.length !== kb.length) return false;
      for (const key of ka) {
        if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
        if (!pyEqual(a[key], b[key])) return false;
      }
      return true;
    }
    default:
      return a === b;
  }
}

