// ValidationError: mirrors jsonschema.exceptions.ValidationError.
// Observable attributes: `path` (instance location, used by ErrorTree),
// `validator` (the keyword that failed; ErrorTree keys errors on it) and
// `context` (sub-errors of anyOf/oneOf failures, not part of the tree).

export class ValidationError extends Error {
  constructor(message, path = [], validator = "", context = []) {
    super(message);
    this.name = "ValidationError";
    this.message = message;
    this.path = path;
    this.validator = validator;
    this.context = context;
  }
}

// SchemaError: raised by check_schema (and by un-crawlable schemas, mirroring
// the `referencing` library failures) when a schema is invalid. The Python
// program crashes with a traceback in these cases; the entry point exits
// non-zero without writing to stdout, matching that observable behaviour.

export class SchemaError extends Error {
  constructor(message) {
    super(message);
    this.name = "SchemaError";
  }
}

